 controls=new LinearLayout(this);controls.setOrientation(LinearLayout.VERTICAL);controls.setPadding(dp(16),dp(7),dp(16),dp(9));controls.setBackground(draw(themeColor(0x88)));FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);cp.setMargins(dp(20),0,dp(20),dp(16));root.addView(controls,cp);
 LinearLayout progress=new LinearLayout(this);progress.setGravity(Gravity.CENTER_VERTICAL);elapsed=label("00:00",12);duration=label(live?"LIVE":"00:00",12);progress.addView(elapsed);timeline=new SeekBar(this);timeline.setMax(100000);timeline.setOnKeyListener((v,code,event)->{if(code!=KeyEvent.KEYCODE_DPAD_LEFT&&code!=KeyEvent.KEYCODE_DPAD_RIGHT)return false;if(event.getAction()==KeyEvent.ACTION_DOWN)beginScrub(code,event.getRepeatCount()>0);else if(event.getAction()==KeyEvent.ACTION_UP)finishScrub(true,true);return true;});timeline.setOnFocusChangeListener((v,f)->{if(!f)finishScrub(false,true);});timeline.setEnabled(!live);progress.addView(timeline,new LinearLayout.LayoutParams(0,dp(28),1));progress.addView(duration);controls.addView(progress);
 LinearLayout info=new LinearLayout(this);info.setGravity(Gravity.CENTER_VERTICAL);ImageView poster=new ImageView(this);channelPoster=poster;poster.setScaleType(ImageView.ScaleType.FIT_CENTER);info.addView(poster,new LinearLayout.LayoutParams(dp(34),dp(46)));LinearLayout copy=new LinearLayout(this);copy.setOrientation(LinearLayout.VERTICAL);copy.setPadding(dp(10),0,0,0);TextView title=label(getIntent().getStringExtra("name"),18);channelTitle=title;title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);copy.addView(title);copy.addView(label("Morph IPTV"+(live?" · LIVE":""),10));info.addView(copy,new LinearLayout.LayoutParams(0,-2,1));controls.addView(info);
