 timeline.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){finishScrub(false,true);dragging=true;touchWasPlaying=prepared&&video.isPlaying();if(touchWasPlaying)video.pause();timer.removeCallbacks(hide);}public void onStopTrackingTouch(SeekBar b){dragging=false;resumeAfterSeek=touchWasPlaying;commitSeek();if(!seekingResume&&touchWasPlaying&&prepared)video.start();touchWasPlaying=false;scheduleHide();}public void onProgressChanged(SeekBar b,int value,boolean user){if(user&&prepared&&!live){elapsed.setText(clock((int)(video.getDuration()*(value/100000.0))));if(!dragging)commitSeek();}if(user)scheduleHide();}});
